-- Rating distribution tables: store multiple named matrices.
-- column_range_start: participant count for the first column (step always 2).
-- matrix: rows = places (1-based index), cols = participant ranges; null = no points.
CREATE TABLE IF NOT EXISTS rating_tables (
  id                   SERIAL  PRIMARY KEY,
  name                 TEXT    NOT NULL,
  column_range_start   INTEGER NOT NULL,
  column_range_step    INTEGER NOT NULL DEFAULT 2,
  matrix               JSONB   NOT NULL
);

